-- Schema for community_service, implementing docs/architecture.md §5 verbatim.
-- All timestamps are timestamptz (UTC) and all identifiers are UUID v4 values
-- generated by the service.

CREATE TABLE communities (
    id            uuid PRIMARY KEY,
    name          varchar(100) NOT NULL,
    description   varchar(500) NULL,
    icon_url      text NULL,
    owner_user_id uuid NOT NULL,
    created_at    timestamptz NOT NULL,
    updated_at    timestamptz NOT NULL
);

CREATE TABLE channels (
    id              uuid PRIMARY KEY,
    community_id    uuid NOT NULL REFERENCES communities (id) ON DELETE CASCADE,
    kind            text NOT NULL CHECK (kind IN ('text', 'voice')),
    name            varchar(100) NOT NULL,
    position        integer NOT NULL DEFAULT 0,
    capacity        integer NULL CHECK (capacity BETWEEN 1 AND 10),
    channel_version bigint NOT NULL DEFAULT 1,
    created_at      timestamptz NOT NULL,
    updated_at      timestamptz NOT NULL,
    CONSTRAINT channels_community_id_name_key UNIQUE (community_id, name)
);

CREATE INDEX channels_community_id_position_idx ON channels (community_id, position);

CREATE TABLE invites (
    id           uuid PRIMARY KEY,
    community_id uuid NOT NULL REFERENCES communities (id) ON DELETE CASCADE,
    code         varchar(32) NOT NULL UNIQUE,
    created_by   uuid NOT NULL,
    expires_at   timestamptz NULL,
    max_uses     integer NULL CHECK (max_uses >= 1),
    use_count    integer NOT NULL DEFAULT 0,
    revoked_at   timestamptz NULL,
    created_at   timestamptz NOT NULL
);

CREATE INDEX invites_community_id_idx ON invites (community_id);

CREATE TABLE memberships (
    id             uuid PRIMARY KEY,
    community_id   uuid NOT NULL REFERENCES communities (id) ON DELETE CASCADE,
    user_id        uuid NOT NULL,
    status         text NOT NULL CHECK (status IN ('active', 'removed')),
    joined_at      timestamptz NOT NULL,
    left_at        timestamptz NULL,
    muted_until    timestamptz NULL,
    member_version bigint NOT NULL DEFAULT 1,
    CONSTRAINT memberships_community_id_user_id_key UNIQUE (community_id, user_id)
);

CREATE INDEX memberships_community_id_active_idx ON memberships (community_id) WHERE status = 'active';
CREATE INDEX memberships_user_id_idx ON memberships (user_id);

CREATE TABLE community_bans (
    id           uuid PRIMARY KEY,
    community_id uuid NOT NULL REFERENCES communities (id) ON DELETE CASCADE,
    user_id      uuid NOT NULL,
    reason       varchar(1000) NULL,
    banned_at    timestamptz NOT NULL,
    lifted_at    timestamptz NULL
);

CREATE UNIQUE INDEX community_bans_active_key ON community_bans (community_id, user_id) WHERE lifted_at IS NULL;

CREATE TABLE roles (
    id           uuid PRIMARY KEY,
    community_id uuid NOT NULL REFERENCES communities (id) ON DELETE CASCADE,
    name         varchar(100) NOT NULL,
    permissions  text[] NOT NULL DEFAULT '{}',
    position     integer NOT NULL,
    created_at   timestamptz NOT NULL,
    updated_at   timestamptz NOT NULL,
    CONSTRAINT roles_community_id_name_key UNIQUE (community_id, name),
    CONSTRAINT roles_community_id_position_key UNIQUE (community_id, position)
);

CREATE TABLE member_roles (
    community_id uuid NOT NULL REFERENCES communities (id) ON DELETE CASCADE,
    user_id      uuid NOT NULL,
    role_id      uuid NOT NULL REFERENCES roles (id) ON DELETE CASCADE,
    assigned_at  timestamptz NOT NULL,
    PRIMARY KEY (community_id, user_id, role_id)
);

CREATE TABLE processed_events (
    event_id     uuid PRIMARY KEY,
    event_type   text NOT NULL,
    processed_at timestamptz NOT NULL
);
